import {
  LinearSRGBColorSpace,
  RepeatWrapping,
  SRGBColorSpace,
  Texture,
  TextureLoader,
} from 'three';

const BASE = import.meta.env.BASE_URL + 'assets/textures/';
const cache = new Map<string, Texture>();

/**
 * Tileable map from public/assets/textures (generated by tools/makeTextureAtlas.py and
 * tools/makeWallTextures.py). Browser only: tests run in node with no DOM and get null, so
 * materials keep their flat colours there.
 */
export function tileTexture(name: string): Texture | null {
  if (typeof document === 'undefined') return null;
  let t = cache.get(name);
  if (!t) {
    t = new TextureLoader().load(BASE + name + '.jpg');
    t.wrapS = RepeatWrapping;
    t.wrapT = RepeatWrapping;
    t.colorSpace = SRGBColorSpace;
    t.anisotropy = 4;
    cache.set(name, t);
  }
  return t;
}

/** Matching tangent-space normal map (<name>_n.jpg, tools/makeNormalMaps.py); null in node. */
export function tileNormal(name: string): Texture | null {
  if (typeof document === 'undefined') return null;
  const key = name + '_n';
  let t = cache.get(key);
  if (!t) {
    t = new TextureLoader().load(BASE + key + '.jpg');
    t.wrapS = RepeatWrapping;
    t.wrapT = RepeatWrapping;
    t.colorSpace = LinearSRGBColorSpace;
    t.anisotropy = 4;
    cache.set(key, t);
  }
  return t;
}
